defaults.entrypoint:
package main

import (
    "fmt"
    "net/http"
)

func main() {
    http.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
        fmt.Fprintf(w, `{"status":"ok","version":"1.0.0"}`)
    })
    http.ListenAndServe(":8080", nil)
}

pipelineScript:
pipeline {
  agent { docker { image 'golang:1.22-alpine' } }
  stages {
    stage('Checkout') {
      steps { git branch: 'main', url: 'https://github.com/acme/auth-gw' }
    }
    stage('Security Scan') {
      steps { sh 'trivy fs --severity HIGH,CRITICAL .' }
    }
    stage('Test') {
      steps { sh 'go test -v -race ./...' }
    }
    stage('Hermetic Package') {
      steps { sh 'docker build -t app:${BUILD_NUMBER} .' }
    }
    stage('Deploy') {
      steps { devflowDeploy canaryRatio: 0.1, autoRollback: true }
    }
  }
}
